// ─────────────────────────────────────────────────────────────────────────────
// Pri Learning · the third-party licence notices, behind an import()
//
// docs/legal/third-party/NOTICES.md is generated by tools/third-party-notices.mjs
// from the client's lockfile and the Android library catalogue: every package
// that ships inside the app, with the licence text its authors published. It
// is tens of kilobytes of licence prose that almost nobody opens, so it is
// reached only by import() from the Legal page, for the same reason the Hindi
// notices are (i18n/legalHindi.js): a reader who never asks for it never
// downloads it. Nothing but the document is imported here, so the chunk carries
// the notices and nothing else.
// ─────────────────────────────────────────────────────────────────────────────
import notices from '../../../docs/legal/third-party/NOTICES.md?raw';

export default notices;
